# -*- coding: utf-8 -*-
import re
p='src/lalka-2/work/chapter-01/scaffold.txt'
t={265:'Очі баронеси висохли.',266:'— Та звичайно, — перебила вона, — ви мусите їх вигнати... Але, пане! — вигукнула, — хоч вони й лихі та розпусні, та ще гірша за них ота... ота Ставська!...',267:'Я здивувався, побачивши спалах ненависті в очах пані баронеси, коли вона вимовила ім’я Ставської.',268:'— Пані Ставська тут мешкає? — мимоволі спитав я. — Та красуня?...',269:'— О... нова жертва!... — вигукнула баронеса, показуючи на мене, і з палаючими очима заговорила глибоким голосом:',270:'— Та схаменіться, сивоголовий чоловіче, подумайте, що робите?... Адже це жінка, чоловіка якої звинуватили у вбивстві, і він утік за кордон... А з чого вона живе?... Звідки в неї такі вбрання?...',271:'— Жінка працює, як віл, — прошепотів управитель.',272:'— О... і цей теж!... — вигукнула баронеса. — Мій чоловік (я певна, що це він) надсилає їй із села букети... Управитель цього дому закоханий у неї й щомісяця бере з неї квартирну плату...',273:'— Та що ви, пані!... — заперечив екс-поміщик, і обличчя його почервоніло, мов ніс.',274:'— Навіть цей добрий недотепа Марушевич, — провадила баронеса, — навіть він цілими днями виглядає до неї у вікно...',275:'Драматичний голос баронеси знову перейшов у схлипування.',276:'— І подумати тільки, — стогнала вона, — що така жінка має доньку, доньку... яку виховує для пекла, а я... О, я вірю у справедливість... вірю в Боже милосердя, але не розумію... нічого не розумію тих вироків, що позбавили мене дитини, а їй залишили... цій... цій... Господи!',277:'— з новою силою вигукнула вона, — можеш залишити навіть тих нігілістів, але її... мусиш вигнати!... Нехай помешкання після неї стоїть порожнім... я платитиму за нього, аби тільки вона не мала даху над головою...',278:'Цей вигук мені вже зовсім не сподобався. Я дав управителеві знак, що ми йдемо, і, вклонившись, холодно сказав:',279:'— Дозвольте, пані баронесо, щоб у цій справі вирішив сам господар, пан Вокульський.',280:'Баронеса розкинула руки, наче людина, поранена кулею в груди.',281:'— Ах!... То ось як?... — прошепотіла вона. — То вже й ви, і... цей, цей... Вокульський заодно з нею?... Га!... Тоді чекатиму на Божу справедливість...',282:'Ми вийшли, і нас більше не затримували; на сходах я похитнувся, мов п’яний.',283:'— Що ви знаєте про цю пані Ставську? — спитав я Вірського.',284:'— Найчесніша жінка, — відповів він. — Молода, гарна й працює на всю сім’ю... Бо пенсії її матері ледве вистачає на квартирну плату...'}
ls=open(p,encoding='utf-8').read().splitlines();i=-1;o=[]
for l in ls:
 if l.startswith('**PL:**'):i+=1
 if l=='**UA:**' and i in t:l='**UA:** '+t[i]
 o.append(l)
